import type { ReactNode } from "react";

// Renders the brief's Markdown. The brief is generated by assembleBrief(), so only
// that subset is supported: "# " / "## " headings, "- " list items, an italic note
// line, **bold**, `code` and backslash escapes. Text is rendered through React (no
// raw HTML), and trailing "[FEAT-1, QA-2]" citations become chips.

const CITATIONS = /\s\[((?:[A-Z]+-\d+)(?:, [A-Z]+-\d+)*)\]$/;

function renderInline(text: string): ReactNode[] {
  const nodes: ReactNode[] = [];
  let buffer = "";
  let i = 0;
  const flush = () => {
    if (buffer) nodes.push(buffer);
    buffer = "";
  };
  while (i < text.length) {
    const ch = text[i];
    if (ch === "\\" && i + 1 < text.length) {
      buffer += text[i + 1];
      i += 2;
    } else if (text.startsWith("**", i)) {
      const end = text.indexOf("**", i + 2);
      if (end === -1) {
        buffer += ch;
        i++;
        continue;
      }
      flush();
      nodes.push(<strong key={nodes.length}>{text.slice(i + 2, end)}</strong>);
      i = end + 2;
    } else if (ch === "`") {
      const end = text.indexOf("`", i + 1);
      if (end === -1) {
        buffer += ch;
        i++;
        continue;
      }
      flush();
      nodes.push(
        <code key={nodes.length} className="rounded bg-muted px-1 font-mono text-[0.8em]">
          {text.slice(i + 1, end)}
        </code>,
      );
      i = end + 1;
    } else {
      buffer += ch;
      i++;
    }
  }
  flush();
  return nodes;
}

function ListItem({ text }: { text: string }) {
  const match = CITATIONS.exec(text);
  const body = match ? text.slice(0, match.index) : text;
  return (
    <li className="leading-relaxed">
      {renderInline(body)}
      {match && (
        <span className="ml-1.5 inline-flex flex-wrap gap-1 align-middle">
          {match[1].split(", ").map((id) => (
            <span key={id} className="rounded border bg-muted/60 px-1 font-mono text-[0.68rem] text-muted-foreground">
              {id}
            </span>
          ))}
        </span>
      )}
    </li>
  );
}

export function BriefDocument({ markdown }: { markdown: string }) {
  const blocks: ReactNode[] = [];
  let list: string[] = [];
  const flushList = () => {
    if (list.length === 0) return;
    blocks.push(
      <ul key={blocks.length} className="ml-5 list-disc space-y-1.5 text-sm marker:text-muted-foreground">
        {list.map((item, i) => (
          <ListItem key={i} text={item} />
        ))}
      </ul>,
    );
    list = [];
  };

  for (const line of markdown.split("\n")) {
    if (line.startsWith("- ")) {
      list.push(line.slice(2));
      continue;
    }
    flushList();
    if (line.startsWith("# ")) {
      blocks.push(
        <h1 key={blocks.length} className="font-heading text-2xl font-semibold tracking-tight">
          {renderInline(line.slice(2))}
        </h1>,
      );
    } else if (line.startsWith("## ")) {
      blocks.push(
        <h2 key={blocks.length} className="mt-4 border-b pb-1 font-heading text-lg font-semibold">
          {renderInline(line.slice(3))}
        </h2>,
      );
    } else if (/^_.*_$/.test(line)) {
      blocks.push(
        <p key={blocks.length} className="text-sm italic text-muted-foreground">
          {renderInline(line.slice(1, -1))}
        </p>,
      );
    } else if (line.trim()) {
      blocks.push(
        <p key={blocks.length} className="text-sm">
          {renderInline(line)}
        </p>,
      );
    }
  }
  flushList();
  return (
    <article className="space-y-3" data-testid="brief-document">
      {blocks}
    </article>
  );
}
